import App from './App'
import { pagePullDownRefreshMixin } from './utils/pagePullDownRefresh.js'

// #ifndef VUE3
import Vue from 'vue'
import './uni.promisify.adaptor'
Vue.config.productionTip = false
Vue.mixin(pagePullDownRefreshMixin)
App.mpType = 'app'
const app = new Vue({
  ...App
})
app.$mount()
// #endif

// #ifdef VUE3
import { createSSRApp } from 'vue'
export function createApp() {
  const app = createSSRApp(App)
  app.mixin(pagePullDownRefreshMixin)
  return {
    app
  }
}
// #endif
